import{_ as t,o as r,c as o,a5 as a}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"命名视图","description":"有时候想同时 (同级) 展示多个视图，而不是嵌套展示，例如创建一个布局，有 sidebar (侧导航) 和 main (主内容) 两个视图，这个时候命名视图就派上用场了。你可以在界面中拥有多个单独命名的视图，而不是只有一个单独的出口。如果 router view 没有设置名字，那。","frontmatter":{"title":"命名视图","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"有时候想同时 (同级) 展示多个视图，而不是嵌套展示，例如创建一个布局，有 sidebar (侧导航) 和 main (主内容) 两个视图，这个时候命名视图就派上用场了。你可以在界面中拥有多个单独命名的视图，而不是只有一个单独的出口。如果 router view 没有设置名字，那。","sidebarWeight":32,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/命名视图.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/命名视图.md","filePath":"posts/Vue系统教程/04-路由与状态管理/命名视图.md"}'),i={name:"posts/Vue系统教程/04-路由与状态管理/命名视图.md"};function s(l,e,n,u,d,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<div><h1 id="命名视图" tabindex="-1">命名视图 <a class="header-anchor" href="#命名视图" aria-label="Permalink to &quot;命名视图&quot;">​</a></h1><blockquote><p>本节目标：理解“命名视图”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 有时候想同时 (同级) 展示多个视图，而不是嵌套展示，例如创建一个布局，有 sidebar (侧导航) 和 main (主内容) 两个视图，这个时候命名视图就派上用场了。你可以在界面中拥有多个单独命名的视图，而不是只有一个单独的出口。如果 router-view 没有设置名字，那么默认为 default。 &lt;router-view class=&quot;view left-sidebar&quot; name=&quot;LeftSidebar&quot;&gt;&lt;/router-view&gt; &lt;router-view class=&quot;view main-content&quot;&gt;&lt;/router-view&gt; &lt;router-view class=&quot;view right-sidebar&quot; name=&quot;RightSidebar&quot;&gt;&lt;/router-view&gt;</p></blockquote><p>一个视图使用一个组件渲染，因此对于同个路由，多个视图就需要多个组件。确保正确使用 components 配置 (带上 s)： const router = createRouter({ history: createWebHashHistory(), routes: [ { path: &#39;/&#39;, components: { default: Home, // LeftSidebar: LeftSidebar 的缩写 LeftSidebar, // 它们与 <code>\\&lt;router-view\\&gt;</code> 上的 <code>name</code> 属性匹配 RightSidebar, }, }, ], }) 以上案例相关的可运行代码请<a href="https://codesandbox.io/s/named-views-vue-router-4-examples-rd20l" target="_blank" rel="noreferrer">移步这里</a>.</p><p><strong>嵌套命名视图</strong> 我们也有可能使用命名视图创建嵌套视图的复杂布局。这时你也需要命名用到的嵌套 router-view 组件。我们以一个设置面板为例：</p><ul><li>Nav 只是一个常规组件。</li><li>UserSettings 是一个视图组件。</li><li>UserEmailsSubscriptions、UserProfile、UserProfilePreview 是嵌套的视图组件。</li></ul><p>注意：我们先忘记 HTML/CSS 具体的布局的样子，只专注在用到的组件上。</p><p>UserSettings 组件的 &lt;template&gt; 部分应该是类似下面的这段代码: html &lt;!-- UserSettings.vue --&gt; &lt;div&gt; &lt;h1&gt;User Settings&lt;/h1&gt; &lt;NavBar /&gt; &lt;router-view /&gt; &lt;router-view name=&quot;helper&quot; /&gt; &lt;/div&gt;</p><p>那么你就可以通过这个路由配置来实现上面的布局： { path: &#39;/settings&#39;, // 你也可以在顶级路由就配置命名视图 component: UserSettings, children: [{ path: &#39;emails&#39;, component: UserEmailsSubscriptions }, { path: &#39;profile&#39;, components: { default: UserProfile, helper: UserProfilePreview } }] } 以上案例相关的可运行代码请<a href="https://codesandbox.io/s/nested-named-views-vue-router-4-examples-re9yl?&amp;initialpath=%2Fsettings%2Femails" target="_blank" rel="noreferrer">移步这里</a>.</p></div>',1)])])}const g=t(i,[["render",s]]);export{m as __pageData,g as default};
